type Tab = "meta" | "issues";
const tab = ref<Tab>("meta");

watch(
  () => props.findings.length,
  (n, prev) => {
    // Prefer Issues when findings first appear; don't yank the user off Meta later.
    if (n > 0 && (prev === undefined || prev === 0) && tab.value === "meta") {
      tab.value = "issues";
    }
  },
  { immediate: true },
);

  await flushPromises();
  const sidebar = w.get("[data-testid='page-details-sidebar']");
  // eslint-disable-next-line no-console
  console.log("SIDEBAR", sidebar.html());
  expect(sidebar.html()).toContain("Title");
  expect(sidebar.html()).toContain("Welcome");
  w.unmount();
});

